class TestHardVote(unittest.TestCase):
    def test_basic_vote(self):
        fit = {
            'classes': ['red', 'blue'],
            'members': [
                {'fit_weight': 1, 'predictions': ['blue', 'red']},
                {'fit_weight': 3, 'predictions': ['red', 'red']},
            ],
        }
        contract = {'name': 'hard', 'operation': 'hard_vote', 'inputs': ['x']}
        result = transform([fit], contract)
        self.assertEqual(set(result), {'name', 'result'})
        self.assertEqual(result['name'], 'hard')
        self.assertEqual(result['result']['predictions'], ['red', 'red'])
        self.assertEqual(result['result']['scores'], [[3.0, 1.0], [4.0, 0.0]])

    def test_tie_breaks_by_class_order(self):
        fit = {
            'classes': ['red', 'blue'],
            'members': [
                {'fit_weight': 1, 'predictions': ['blue']},
                {'fit_weight': 1, 'predictions': ['red']},
            ],
        }
        contract = {'name': 'hard', 'operation': 'hard_vote', 'inputs': ['x']}
        result = transform([fit], contract)
        self.assertEqual(result['result']['predictions'], ['red'])

